INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f27b563c-6f42-42ae-9c21-029b44359198', 'c3c3c3c3-3030-4000-8000-000000000003', 13, 'Dia 13 — Verdade', 'Semana 2: Organizar', '{"pch": "Conhecereis a verdade e a verdade vos libertar\u00e1\u2026 Mentiras internas aprisionam. A verdade liberta.", "verse": "Jo 8,32", "lectio": "Leia Jo 8,31-36. A liberdade real.", "practice": "Escreva a mentira. Ao lado, escreva a verdade de Deus sobre voc\u00ea.", "question": "Que mentira sobre si mesmo voc\u00ea acreditou por tempo demais?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;